package corpus.catchpolicy

fun readOrFallback(read: () -> String): String = try {
    read()
} catch (failure: Exception) {
    "unavailable"
}

fun closeOrFalse(close: () -> Unit): Boolean = try {
    close()
    true
} catch (failure: Throwable) {
    false
}

